import { step } from "../world/movement.js";
import { bounce } from "../world/bounds.js";

const BELL = "rgba(180, 120, 220, 0.8)";
const BELL_EDGE = "plum";
const TENTACLE = "rgba(200, 160, 240, 0.6)";

export function spawn() {
  return {
    x: 100 + Math.random() * 600,
    y: 120 + Math.random() * 250,
    vx: 0.15,
    vy: 0.6,
    phase: Math.random() * Math.PI * 2,
  };
}

export function update(jelly, world) {
  // gentle pulse: drift up and down on a slow wave
  jelly.vy = Math.sin(jelly.age * 0.03 + jelly.phase) * 0.8;
  jelly.vx += Math.sin(jelly.age * 0.017 + jelly.phase) * 0.005;
  step(jelly);
  bounce(jelly);
}

export function draw(jelly, pen) {
  const squish = 1 + 0.12 * Math.sin(jelly.age * 0.06 + jelly.phase);
  pen.fill(TENTACLE);
  for (let i = -2; i <= 2; i++) {
    pen.line(i * 6, 8, i * 6 + Math.sin(jelly.age * 0.05 + i) * 5, 26);
  }
  pen.fill(BELL);
  pen.ellipse(0, 0, 16 * squish, 12 / squish);
  pen.stroke(BELL_EDGE);
  pen.arc(0, 2, 12, 0, Math.PI);
}

