// A seahorse that bobs gently up and down.
import { step } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";

const BODY = "orange";
const BRIGHT = "gold";
const EYE = "black";

export function spawn(world) {
  return {
    phase: Math.random() * Math.PI * 2,
    drift: Math.random() * Math.PI * 2
  };
}

export function update(seahorse, world) {
  seahorse.phase += 0.05;
  seahorse.drift += 0.011;
  seahorse.vx = Math.sin(seahorse.drift) * 0.2;
  seahorse.vy = Math.cos(seahorse.phase) * 0.6;
  step(seahorse);
  keepInside(seahorse);
}

export function draw(seahorse, pen) {
  // curled tail
  pen.stroke(BODY, 3);
  pen.arc(2, 16, 9, 0.9, Math.PI * 1.7);
  // body
  pen.fill(BODY);
  pen.ellipse(0, 4, 7, 13, 0.25);
  // head and snout
  pen.fill(BRIGHT);
  pen.ellipse(3, -12, 6, 5.5, -0.5);
  pen.fill(BODY);
  pen.rect(4, -16, 11, 4, 2);
  // fin and eye
  pen.fill(BRIGHT);
  pen.poly([-6, -2, -15, -8, -13, 4]);
  pen.fill(EYE);
  pen.circle(5, -13, 1.5);
