import { FLOOR_Y } from "../world/bounds.js";

const ARM = "orange";
const TIP = "yellow";
const DOT = "brown";

export const count = 2;

export function spawn(world) {
  return {
    x: Math.random() * 700 + 50,
    y: FLOOR_Y + 8,
    vx: 0,
    vy: 0,
    angle: Math.random() * Math.PI * 2,
    speed: 0.0008 + Math.random() * 0.0008,
  };
}

export function update(starfish, world) {
  starfish.angle += starfish.speed;
}

export function draw(starfish, pen) {
  pen.fill(ARM);
  for (let i = 0; i < 5; i += 1) {
    const a = starfish.angle + (i * Math.PI * 2) / 5;
    const tipX = Math.cos(a) * 16;
    const tipY = Math.sin(a) * 16 * 0.5;
    const midX = Math.cos(a + 0.5) * 6;
    const midY = Math.sin(a + 0.5) * 3;
    const otherX = Math.cos(a - 0.5) * 6;
    const otherY = Math.sin(a - 0.5) * 3;
    pen.poly([0, 0, midX, midY, tipX, tipY, otherX, otherY]);
  }
  pen.fill(TIP);
  for (let i = 0; i < 5; i += 1) {
    const a = starfish.angle + (i * Math.PI * 2) / 5;
    pen.circle(Math.cos(a) * 14, Math.sin(a) * 7, 2.5);
  }
  pen.fill(DOT);
  pen.circle(0, 0, 3);
}

