// A sea urchin sitting on the sand, waving its spines slowly.
import { POOL_WIDTH, FLOOR_Y } from "../world/bounds.js";

const BODY = "purple";
const SPINE = "black";
const TUBE_FOOT = "pink";

const SPINES = 18;

// Wave phase in radians: the spines swing around the upright direction.
function sway(creature, i) {
  return Math.sin(creature.age * 0.05 + i * 1.7) * 0.25;
}

export function spawn(world) {
  return {
    x: Math.random() * POOL_WIDTH,
    y: FLOOR_Y - 8,
    vx: 0,
    vy: 0,
  };
}

export function update(creature) {
  creature.vx = 0;
  creature.vy = 0;
}

export function draw(creature, pen) {
  // Body
  pen.fill(BODY);
  pen.stroke(SPINE, 2);
  pen.circle(0, 0, 14);

  // Spines radiating out, each swaying a little.
  pen.stroke(SPINE, 2);
  for (let i = 0; i < SPINES; i++) {
    const a = (i / SPINES) * Math.PI * 2 + sway(creature, i);
    const cos = Math.cos(a);
    const sin = Math.sin(a);
    pen.line(14 * cos, 14 * sin, 30 * cos, 30 * sin);
  }

  // A few pink tube feet between the spines.
  pen.stroke(TUBE_FOOT, 2);
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2 + sway(creature, i + 3) * 1.6;
    const cos = Math.cos(a);
    const sin = Math.sin(a);
    pen.line(10 * cos, 10 * sin, 22 * cos, 22 * sin);
  }
}

