import { step } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";
import { isNight } from "../world/time.js";

// Manta ray: glides in wide, slow circles, rises a little at night.
const TOP = "#3a4a6b";
const UNDER = "#8fa8c8";
const EYE = "#101828";

const TURN = 0.01;   // radians per tick: one wide circle takes about 10 s
const SPEED = 0.8;   // slow glide speed

export function spawn() {
  return {
    vx: SPEED,
    vy: 0,
    turn: TURN,
    wing: 0,          // wing beat phase, in radians
  };
}

export function update(manta, world) {
  // Turn gently in one direction; keep speed constant so the path stays a circle.
  const s = Math.hypot(manta.vx, manta.vy) || SPEED;
  const c = Math.cos(manta.turn);
  const sn = Math.sin(manta.turn);
  const dx = (manta.vx / s) * c - (manta.vy / s) * sn;
  const dy = (manta.vx / s) * sn + (manta.vy / s) * c;
  manta.vx = dx * SPEED;
  manta.vy = dy * SPEED;

  // Night: a small lift.
  manta.vy -= isNight(world) ? 0.004 : 0;

  manta.wing += 0.05;

  step(manta);
  keepInside(manta);
}

export function draw(manta, pen) {
  if (manta.vx < 0) pen.flip();
  pen.alpha(0.25 + 0.2 * Math.sin(manta.wing));   // soft shadowy glow of the underside
  pen.fill(UNDER);
  pen.ellipse(0, 6, 26, 10);
  pen.alpha(1);
  pen.fill(TOP);
  pen.poly([-30, 0, -6, -12, 18, -6, 26, 0, 18, 6, -6, 12]);   // wide diamond wings
  pen.poly([-30, 0, -40, -7, -38, 0, -40, 7]);                 // thin tail
  pen.fill(EYE);
  pen.circle(18, -4, 1.5);
}

