import { ENERGY_MAX, isHungry } from "../world/energy.js";
import { nearestFood } from "../world/food.js";
import { step, steer, glide } from "../world/movement.js";
import { bounce } from "../world/bounds.js";
import { isNight } from "../world/time.js";

const NIGHT_BODY = "darkslateblue";
const NIGHT_ARM = "midnightblue";
const DAY_BODY = "coral";
const DAY_ARM = "darkorange";

export const count = 2;

export function spawn() {
  return { vx: 0.4, vy: 0.1, energy: ENERGY_MAX };
}

export function update(octopus, world) {
  const food = isHungry(octopus) ? nearestFood(octopus, world) : null;
  if (food) steer(octopus, food.x, food.y, 0.1);
  else {
    const night = isNight(world);
    // sluggish in the dark, curious in the light
    const wobble = (octopus.age % 120 < 60 ? 60 : -60);
    steer(octopus, octopus.x + (octopus.vx < 0 ? -wobble : wobble), octopus.y, night ? 0.02 : 0.06);
  }
  glide(octopus, 0.95);
  step(octopus);
  bounce(octopus);
}

export function draw(octopus, pen, world) {
  const night = isNight(world);
  const BODY = night ? NIGHT_BODY : DAY_BODY;
  const ARM = night ? NIGHT_ARM : DAY_ARM;
  if (octopus.vx < 0) pen.flip();
  // arms
  pen.fill(ARM);
  for (let i = -3; i <= 3; i++) {
    pen.ellipse(i * 8, 16, 3.5, 12 + (i % 2) * 3, i * 0.12);
  }
  // mantle
  pen.fill(BODY);
  pen.ellipse(0, 0, 18, 16);
  // eyes
  pen.fill("black");
  pen.circle(6, -4, 3);
  pen.circle(-6, -4, 3);
}

