import { step, steer, glide } from "../world/movement.js";
import { wrap } from "../world/bounds.js";

const BODY = "royalblue";
const FIN = "lightsteelblue";
const EYE = "black";

export const count = 8;

export function spawn() {
  return { vx: 1.2, vy: 0 };
}

export function update(fish, world) {
  // Stay together: steer toward the middle of the school.
  const school = world.creatures.filter((c) => c.kind === fish.kind);
  const others = school.filter((c) => c.id !== fish.id);
  if (others.length) {
    const cx = others.reduce((sum, c) => sum + c.x, 0) / others.length;
    const cy = others.reduce((sum, c) => sum + c.y, 0) / others.length;
    steer(fish, cx, cy, 0.08);
  }
  // A gentle shared wander so the school moves as one.
  const drift = Math.sin(fish.age * 0.03) * 0.02;
  fish.vy += drift;
  glide(fish, 0.98);
  step(fish);
  wrap(fish);
}

export function draw(fish, pen) {
  if (fish.vx < 0) pen.flip();
  pen.fill(FIN);
  pen.poly([-12, 0, -24, -9, -24, 9]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 18, 10);
  pen.fill(EYE);
  pen.circle(9, -3, 2);
}

