import { ENERGY_MAX } from "../world/energy.js";
import { step, wander, glide } from "../world/movement.js";
import { keepInside, POOL_WIDTH } from "../world/bounds.js";

const SHELL = "#c0392b";
const CLAW = "#e67e22";
const LEG = "#922b21";

export const count = 2;

export function spawn() {
  return {
    y: 0,
    vx: 1.2,
    vy: 0,
    energy: ENERGY_MAX,
    legPhase: Math.random() * 6,
  };
}

export function update(lobster, world) {
  // walk along the sand
  lobster.vy *= 0.5;
  wander(lobster, 0.02);
  glide(lobster, 0.96);
  step(lobster);

  const before = lobster.x;
  keepInside(lobster);

  // turn around at the walls
  if (lobster.x === 0 && before <= 0) lobster.vx = Math.abs(lobster.vx) || 1;
  if (lobster.x === POOL_WIDTH && before >= POOL_WIDTH) lobster.vx = -Math.abs(lobster.vx) - 0.01;

  lobster.legPhase += Math.abs(lobster.vx) * 0.3;
}

export function draw(lobster, pen) {
  if (lobster.vx < 0) pen.flip();
  const wig = Math.sin(lobster.legPhase);

  // legs
  pen.stroke(LEG, 2);
  pen.line(-6, 4, -13, 9 + wig * 2);
  pen.line(-1, 5, -4, 11 - wig * 2);
  pen.line(5, 5, 8, 11 + wig * 2);

  // tail fan
  pen.fill(SHELL);
  pen.poly([-22, -4, -30, 0, -22, 4]);

  // body
  pen.fill(SHELL);
  pen.ellipse(0, 0, 24, 8);
  // segments
  pen.stroke(LEG, 1);
  pen.line(-8, -7, -8, 7);
  pen.line(2, -7, 2, 7);

  // head
  pen.fill(SHELL);
  pen.ellipse(18, 0, 9, 6);
  pen.fill("black");
  pen.circle(21, -3, 1.5);

  // antennae
  pen.stroke(LEG, 1);
  pen.line(24, -4, 32, -10);
  pen.line(24, -2, 34, -4);

  // claws
  pen.fill(CLAW);
  pen.ellipse(24, 8, 7, 4);
  pen.poly([27, 6, 35, 4, 28, 11]);
}

