import { ENERGY_MAX } from "../world/energy.js";
import { distance, step, steer, glide } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";

const BODY = "skyblue";
const STRIPE = "white";

// One cleaner fish per turtle.
export const count = 2;

// The turtle this fish serves.
function nearestTurtle(fish, world) {
  let best = null;
  let bestFar = Infinity;
  for (const other of world.creatures) {
    if (other.kind !== "turtle" || other === fish) continue;
    const far = distance(fish, other);
    if (far < bestFar) {
      bestFar = far;
      best = other;
    }
  }
  return best;
}

export function spawn(world) {
  const turtle = world.creatures.find((c) => c.kind === "turtle");
  return {
    x: turtle ? turtle.x + 30 : undefined,
    y: turtle ? turtle.y : undefined,
    vx: 0,
    vy: 0,
    energy: ENERGY_MAX,
  };
}

export function update(fish, world) {
  const turtle = nearestTurtle(fish, world);
  if (turtle) {
    // Swim just behind and above the turtle's shell.
    const side = turtle.vx >= 0 ? 1 : -1;
    const spot = { x: turtle.x - side * 26, y: turtle.y - 12 };
    if (distance(fish, spot) > 10) steer(fish, spot.x, spot.y, 0.3);
  } else {
    steer(fish, fish.x, fish.y + 10, 0.05);
  }
  glide(fish, 0.9);
  step(fish);
  keepInside(fish);
}

export function draw(fish, pen) {
  if (fish.vx < 0) pen.flip();
  pen.fill(BODY);
  pen.ellipse(0, 0, 12, 7);
  pen.fill(STRIPE);
  pen.rect(-5, -5, 2, 10);
  pen.rect(1, -5, 2, 10);
  pen.fill("black");
  pen.circle(7, -2, 1.5);
  pen.fill(BODY);
  pen.poly([-12, 0, -19, -5, -19, 5]);
}

