import { ENERGY_MAX } from "../world/energy.js";
import { FLOOR_Y, bounce } from "../world/bounds.js";
import { step } from "../world/movement.js";

const SHELL = "coral";
const CLAW = "coral";
const HIDE_BELOW = ENERGY_MAX * 0.3; // 30 points

export function spawn() {
  return {
    y: FLOOR_Y - 8,
    energy: ENERGY_MAX,
    hidden: false,
  };
}

export function update(crab, world) {
  crab.hidden = crab.energy < HIDE_BELOW;
  if (crab.hidden) {
    crab.vx *= 0.9;
    crab.vy *= 0.9;
  } else if (Math.random() < 0.02) {
    crab.vx += Math.random() * 0.6 - 0.3;
  }
  step(crab);
  bounce(crab);
}

export function draw(crab, pen) {
  if (crab.hidden) {
    // tucked in: only the closed shell, on the floor
    pen.fill(SHELL);
    pen.ellipse(0, 0, 16, 9);
    pen.line(-14, 6, 14, 6);
  } else {
    // legs
    pen.stroke(CLAW);
    pen.line(-10, 6, -18, 12);
    pen.line(-4, 7, -6, 14);
    pen.line(4, 7, 6, 14);
    pen.line(10, 6, 18, 12);
    // claws
    pen.circle(-14, -6, 4);
    pen.circle(14, -6, 4);
    // body
    pen.fill(SHELL);
    pen.ellipse(0, 0, 16, 10);
    pen.fill("black");
    pen.circle(-4, -3, 2);
    pen.circle(4, -3, 2);
  }
}

