    const angle = Math.random() * 2 * Math.PI;
    shrimp.vx = Math.cos(angle) * DART_SPEED;
    shrimp.vy = Math.sin(angle) * DART_SPEED;
    drain(shrimp, DART_COST);
    shrimp.nextDart = DART_INTERVAL;
  }
  glide(shrimp, 0.95);
  step(shrimp);
  bounce(shrimp);
}

export function draw(shrimp, pen) {
  if (shrimp.vx < 0) pen.flip();
  pen.fill(TAIL);
  pen.poly([-16, -8, -30, 0, -16, 8]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 18, 9);
  pen.ellipse(12, -4, 8, 5);
  pen.fill("black");
  pen.circle(14, -5, 2);
  pen.stroke(BODY);
  pen.line(6, 8, 10, 14);
  pen.line(12, 6, 16, 12);
}

